-- Balance each financial transaction by currency, not an unscoped document sum.
-- This also detects orphan/mismatched header identity on insert.
CREATE OR REPLACE FUNCTION public.ngoda_validate_document_balance()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $function$
DECLARE h public.financial_transaction%rowtype;
BEGIN
  SELECT * INTO h FROM public.financial_transaction WHERE id=NEW.transaction_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FINANCIAL_TRANSACTION_NOT_FOUND'; END IF;
  IF EXISTS (SELECT 1 FROM public.financial_entry e WHERE e.transaction_id=h.id
    AND (e.document_number IS DISTINCT FROM h.document_number
      OR e.country_code IS DISTINCT FROM h.country_code
      OR e.fiscal_year IS DISTINCT FROM h.fiscal_year
      OR e.period IS DISTINCT FROM h.period
      OR e.currency_code IS DISTINCT FROM h.currency_code
      OR e.transaction_type IS DISTINCT FROM h.transaction_type))
  THEN RAISE EXCEPTION 'FINANCIAL_ENTRY_HEADER_MISMATCH: %',h.document_number; END IF;
  IF EXISTS (SELECT 1 FROM public.financial_entry e WHERE e.transaction_id=h.id
    GROUP BY e.currency_code HAVING sum(e.debit) <> sum(e.credit))
  THEN RAISE EXCEPTION 'FINANCIAL_DOCUMENT_NOT_BALANCED: %',h.document_number; END IF;
  RETURN NULL;
END;
$function$;
ALTER FUNCTION public.ngoda_validate_document_balance() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.ngoda_validate_document_balance() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS financial_entry_balance_check ON public.financial_entry;
CREATE CONSTRAINT TRIGGER financial_entry_balance_check AFTER INSERT ON public.financial_entry
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION public.ngoda_validate_document_balance();
-- Wallet entry identity must agree with its existing wallet. Incoming receiver
-- wallets are still created lazily by posting BEFORE the entry is inserted.
CREATE OR REPLACE FUNCTION public.ngoda_validate_wallet_entry_identity()
RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $function$
DECLARE w public.wallet%rowtype;
BEGIN
  SELECT * INTO w FROM public.wallet WHERE id=NEW.wallet_id FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WALLET_NOT_FOUND'; END IF;
  IF NEW.currency_code IS DISTINCT FROM w.currency_code
     OR NEW.country_code IS DISTINCT FROM w.country_code
     OR NEW.blockchain_code IS DISTINCT FROM w.blockchain_code
  THEN RAISE EXCEPTION 'WALLET_ENTRY_IDENTITY_MISMATCH'; END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.ngoda_validate_wallet_entry_identity() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS ngoda_wallet_entry_identity_check ON public.wallet_entry;
CREATE TRIGGER ngoda_wallet_entry_identity_check BEFORE INSERT ON public.wallet_entry
FOR EACH ROW EXECUTE FUNCTION public.ngoda_validate_wallet_entry_identity();
DROP FUNCTION pg_temp.ngoda_add_check(text,text,text);
COMMIT;
